var i=259;var a=[{id:`cooking-259-01`,theoryId:259,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`In direct alginate spherification, where is alginate normally placed?`,ua:`Де зазвичай міститься альгінат під час прямої сферифікації?`},explanation:{en:`Calcium ions cross-link alginate at the droplet interface to form a gel membrane.`,ua:`Іони кальцію зшивають альгінат на поверхні краплі, формуючи гелеву оболонку.`},options:[{id:`a`,text:{en:`In the flavored liquid, with calcium in the setting bath`,ua:`У смаковій рідині, а кальцій — у ванні для формування оболонки`}},{id:`b`,text:{en:`In the oven wall`,ua:`У стінці духовки`}},{id:`c`,text:{en:`Only in dry sugar crystals`,ua:`Лише в сухих кристалах цукру`}}],answer:{optionIds:[`a`]}},{id:`cooking-259-02`,theoryId:259,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`A sphere with a gel membrane is automatically safe even if the filling was contaminated.`,ua:`Сфера з гелевою оболонкою автоматично безпечна, навіть якщо начинка була забруднена.`},explanation:{en:`Spherification alters structure but does not validate food safety.`,ua:`Сферифікація змінює структуру, але не гарантує безпечності продукту.`},answer:{value:!1}},{id:`cooking-259-03`,theoryId:259,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match terms with their role in spherification.`,ua:`Поєднайте терміни з їхньою роллю у сферифікації.`},explanation:{en:`Membrane development depends on diffusion and interaction conditions.`,ua:`Формування оболонки залежить від дифузії та умов взаємодії.`},leftItems:[{id:`l1`,text:{en:`Alginate`,ua:`Альгінат`}},{id:`l2`,text:{en:`Calcium ions`,ua:`Іони кальцію`}},{id:`l3`,text:{en:`Contact time`,ua:`Час контакту`}}],rightItems:[{id:`r2`,text:{en:`Enable alginate cross-linking`,ua:`Забезпечують зшивання альгінату`}},{id:`r3`,text:{en:`Influences membrane growth`,ua:`Впливає на наростання оболонки`}},{id:`r1`,text:{en:`Polymer that forms a calcium-linked network`,ua:`Полімер, що утворює сітку з кальцієм`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-259-04`,theoryId:259,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Spheres have an unexpectedly thick skin after staying in the calcium bath. What should you test?`,ua:`Сфери мають несподівано товсту оболонку після перебування в кальцієвій ванні. Що варто випробувати?`},explanation:{en:`Longer interaction can increase gel formation in many direct setups.`,ua:`Довший контакт може посилювати гелеутворення в багатьох прямих схемах.`},options:[{id:`a`,text:{en:`Let them soak indefinitely`,ua:`Залишити їх у ванні без обмеження часу`}},{id:`b`,text:{en:`Add raw flour to the bath`,ua:`Додати сире борошно у ванну`}},{id:`c`,text:{en:`Shorten the contact time using controlled trials`,ua:`Зменшити час контакту в контрольованих пробах`}}],answer:{optionIds:[`c`]}},{id:`cooking-259-05`,theoryId:259,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which variables should a cook control in spherification?`,ua:`Які змінні потрібно контролювати під час сферифікації?`},explanation:{en:`Chemistry, process control and ingredient safety all matter.`,ua:`Хімія, контроль процесу та безпечність інгредієнтів однаково важливі.`},options:[{id:`a`,text:{en:`Alginate concentration`,ua:`Концентрацію альгінату`}},{id:`b`,text:{en:`Available calcium`,ua:`Доступний кальцій`}},{id:`c`,text:{en:`pH and contact time`,ua:`pH і час контакту`}},{id:`d`,text:{en:`A claim that food safety no longer matters`,ua:`Твердження, що харчова безпека більше не важлива`}}],answer:{optionIds:[`a`,`b`,`c`]}},{id:`cooking-259-06`,theoryId:259,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order the simplified direct-spherification workflow.`,ua:`Упорядкуйте спрощений процес прямої сферифікації.`},explanation:{en:`These steps describe physical technique, not a microbial safety treatment.`,ua:`Ці кроки описують фізичну техніку, а не мікробіологічне знезараження.`},steps:[{id:`s4`,text:{en:`Remove and rinse as appropriate for the recipe`,ua:`Дістати та промити відповідно до рецепта`}},{id:`s1`,text:{en:`Prepare a suitable alginate-containing flavored liquid`,ua:`Підготувати відповідну смакову рідину з альгінатом`}},{id:`s2`,text:{en:`Prepare a measured food-grade calcium bath`,ua:`Підготувати відміряну ванну з харчовим кальцієм`}},{id:`s3`,text:{en:`Form droplets and time their exposure`,ua:`Сформувати краплі та відміряти час контакту`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}},{id:`cooking-259-07`,theoryId:259,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which step is unsafe when making edible alginate spheres?`,ua:`Який крок небезпечний під час виготовлення їстівних альгінатних сфер?`},explanation:{en:`Only appropriately food-grade ingredients and validated methods belong in edible preparations.`,ua:`У їстівних стравах дозволені лише належні харчові інгредієнти та перевірені методи.`},options:[{id:`a`,text:{en:`Use an unidentified industrial calcium chemical in the edible bath`,ua:`Використати невідому промислову сполуку кальцію для їстівної ванни`}},{id:`b`,text:{en:`Measure food-grade alginate and calcium ingredients`,ua:`Відміряти харчові альгінат і сполуки кальцію`}},{id:`c`,text:{en:`Prepare the filling with normal food-safety controls`,ua:`Готувати начинку зі звичайним контролем харчової безпеки`}}],answer:{optionIds:[`a`]}}];var n={theoryId:259,exercises:a};export{n as default,a as exercises,i as theoryId};